  "skills": [
    {
      "id": "about-biorouter",
      "description": "Built-in self-knowledge about Biorouter. Load this skill whenever the user asks about Biorouter itself: what it is, how it works, who built it, or how to use or configure any of its features (extensions, skills, workflows, scheduler, knowledge bases, models and providers, secrets, CLI, or the desktop app)."
    },
    {
      "id": "bioroffice-excel",
      "description": "Create and edit Excel (.xlsx) workbooks with the BiorOffice officecli tool — cells, complex formulas (150+ functions with auto-evaluation), charts, pivot tables, conditional formatting, named ranges, data validation, sorting, and tables."
    },
    {
      "id": "bioroffice-office-suite",
      "description": "Core guide for the BiorOffice officecli tool — create, read, analyze, and modify Word (.docx), Excel (.xlsx), and PowerPoint (.pptx) documents. Covers the tool calling convention, DOM paths, the built-in help system, and dynamic loading of specialized Office skills."
    },
    {
      "id": "bioroffice-powerpoint",
      "description": "Create and edit PowerPoint (.pptx) presentations with the BiorOffice officecli tool — slides, shapes, text styling, images, tables, charts, transitions, animations, and speaker notes."
    },
    {
      "id": "bioroffice-word",
      "description": "Create and edit rich-formatted Word (.docx) documents with the BiorOffice officecli tool — headings, styles, runs, tables, images, headers/footers, TOC, footnotes, hyperlinks, tracked changes, and find/replace."
    },
    {
      "id": "develop-biorouter-extension",
      "description": "Guide for building a Biorouter extension (.brxt file) — covers the required ZIP structure, manifest.json schema, the Python MCP server (pyproject.toml + console-script entry point), cross-platform dependency pitfalls, and optional bundled skills. Load this skill whenever the user wants to build, package, or publish a Biorouter extension."
    },
    {
      "id": "develop-biorouter-skill",
      "description": "Guide for authoring a high-quality Biorouter skill — the SKILL.md format and frontmatter, how Biorouter discovers and loads skills, writing a description that triggers reliably, progressive disclosure with supporting files, composing with subagents/workflows/hooks, testing for consistency and robustness, and packaging a skill as a zip. Load this skill whenever the user wants to create, write, improve, test, or publish a Biorouter (or Claude) skill."
    },
    {
      "id": "ggplot",
      "description": "Publication-quality ggplot2 visualization guide for R. Use when creating new ggplot figures, reviewing existing plots for publication readiness, or refactoring code to improve aesthetics. Covers font sizing, color palettes, themes, label handling, and export settings."
    },
    {
      "id": "medcp-clinical-records",
      "description": "Query electronic health records (OMOP CDM) read-only through MedCP, across SQL Server, MySQL, or a local SQLite file. Use when the user asks to explore clinical tables, build cohorts, or summarize patient data."
    },
    {
      "id": "omop-phenotype-query",
      "description": "Query the UCSF OMOP CDM to identify patient phenotypes and clinical concepts, fast and robustly, using the agent's concept/schema/lab tools."
    },
    {
      "id": "spoke-knowledge-graph",
      "description": "Traverse the SPOKE biomedical knowledge graph to find relationships between diseases, genes, compounds, proteins, pathways, anatomy, side effects and other biological entities"
    },
